js-easy2-sort-by-key.alternative:
const sortBy = (list, pick) => {
  const entries = list.map((item, index) => ({ item, index, key: pick(item) }));
  entries.sort((a, b) => a.key - b.key || a.index - b.index);
  return entries.map(entry => entry.item);
};

