js-easy4-each-line.alternative:
const eachLine = (text, onLine) => {
  let reported = 0;
  text.split("\n").forEach((line, index) => {
    if (line === "") return;
    // The callback decides what to do; we only pass the line and its number.
    onLine(line, index + 1);
    reported++;
  });
  return reported;
};

