js-easy4-report-changes.wrong-inherited:
const applyChanges = (settings, changes, onChange) => {
  let changed = 0;
  for (const key in changes) {
    // Read the old value before it is overwritten.
    const oldValue = settings[key];
    const newValue = changes[key];
    if (oldValue === newValue) continue;
    settings[key] = newValue;
    onChange(key, oldValue, newValue);
    changed++;
  }
  return changed;
};

js-easy4-tick-down.alternative:
const countdown = (from, ms, onTick) => {
  const tick = n => {
    if (n < 1) return;
    onTick(n);
    // Each tick schedules the next one; the last schedules nothing.
    if (n > 1) setTimeout(() => tick(n - 1), ms);
  };
  if (from >= 1) setTimeout(() => tick(from), ms);
};

